import{_ as t,o,c as a,a4 as r}from"./chunks/framework.YC5CMuPM.js";const u=JSON.parse('{"title":"History","description":"","frontmatter":{},"headers":[],"relativePath":"guide/history.md","filePath":"guide/history.md","lastUpdated":1790688230000}'),s={name:"guide/history.md"};function n(i,e,d,l,c,f){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h1><p><strong>JUCE began in the early 2000s as the in-house toolkit behind the Tracktion DAW, became a public framework, changed owners twice, and grew from one monolithic library into today&#39;s 24 modules.</strong> This history explains many of its quirks: its own <code>String</code> and containers, its Projucer, and its naming conventions.</p><div class="info custom-block"><p class="custom-block-title">Sources</p><p>Numbered footnotes link each claim to its source. Version features and module arrival dates come from this repository&#39;s <code>CHANGE_LIST.md</code> and git history. Company events cite public write-ups. Release years for JUCE 4 to 8 are approximate, because this fork&#39;s git history only starts in January 2025 and <code>CHANGE_LIST.md</code> records versions rather than dates. Where a claim could not be sourced, the page says so.</p></div><h2 id="timeline" tabindex="-1">Timeline <a class="header-anchor" href="#timeline" aria-label="Permalink to &quot;Timeline&quot;">​</a></h2><ol class="timeline"><li class="tl-raw"><span class="tl-when">Before 2004</span><strong>Tracktion</strong><span class="tl-what">Julian Storer writes the Tracktion DAW and the cross-platform C++ toolkit underneath it.</span></li><li class="tl-raw"><span class="tl-when">2004</span><strong>Public release</strong><span class="tl-what">The toolkit is released publicly as JUCE, &quot;Jules&#39; Utility Class Extensions&quot;.</span></li><li class="tl-raw"><span class="tl-when">By JUCE 3.x</span><strong>Introjucer</strong><span class="tl-what">The Introjucer project tool is already in use; the 3.x change list mentions it.</span></li><li class="tl-roli"><span class="tl-when">Nov 2014</span><strong>ROLI</strong><span class="tl-what">ROLI acquires JUCE and Raw Material Software.</span></li><li class="tl-roli"><span class="tl-when">2015–16</span><strong>JUCE 4</strong><span class="tl-what">The Projucer arrives (merged with the Introjucer in 4.2), plus OSC support and multi-bus plug-ins.</span></li><li class="tl-roli"><span class="tl-when">2017</span><strong>JUCE 5</strong><span class="tl-what">A new licensing model and C++11/14 modernisation. 5.1 adds <code>juce_dsp</code>.</span></li><li class="tl-pace"><span class="tl-when">2020</span><strong>PACE, JUCE 6</strong><span class="tl-what">PACE Anti-Piracy acquires JUCE (announced April 2020). JUCE 6 adds the CMake API and headless Linux.</span></li><li class="tl-pace"><span class="tl-when">2022</span><strong>JUCE 7</strong><span class="tl-what">LV2 and ARA support and new Apple renderers. MIDI-CI followed in 7.0.9.</span></li><li class="tl-pace"><span class="tl-when">2024</span><strong>JUCE 8</strong><span class="tl-what">Direct2D, WebView UIs, <code>juce_animation</code>, and the move to AGPLv3.</span></li><li class="tl-pace"><span class="tl-when">2026</span><strong>JUCE 9</strong><span class="tl-what">A new SVG parser, variable fonts, a new CoreAudio backend, and OpenGL ES on Linux.</span></li></ol><p class="tl-legend"><span class="tl-raw">Raw Material Software</span><span class="tl-roli">ROLI</span><span class="tl-pace">PACE</span></p><h2 id="eras" tabindex="-1">Eras <a class="header-anchor" href="#eras" aria-label="Permalink to &quot;Eras&quot;">​</a></h2><h3 id="origins-a-toolkit-extracted-from-a-daw" tabindex="-1">Origins: a toolkit extracted from a DAW <a class="header-anchor" href="#origins-a-toolkit-extracted-from-a-daw" aria-label="Permalink to &quot;Origins: a toolkit extracted from a DAW&quot;">​</a></h3><p>Julian Storer (&quot;Jules&quot;) created JUCE as the underlying C++ code of the <strong>Tracktion</strong> digital audio workstation, and JUCE was first released to the public in 2004.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup> Raw Material Software was the company behind it.<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup> The motivation below is inferred from the code&#39;s shape rather than from a source: a DAW needed audio, GUI, and plug-in support that behaved the same on every platform.</p><p>That origin still shows:</p><ul><li><strong>Self-sufficiency.</strong> JUCE has its own <code>String</code>, <code>Array</code>, <code>File</code>, <code>Thread</code>, and smart pointers. It dates from before C++11 made the standard library a reasonable foundation for this kind of code.</li><li><strong>Pragmatism over purity.</strong> The APIs were shaped by what a real DAW needed, including <code>AudioProcessorGraph</code>, <code>AudioThumbnail</code>, and plug-in scanning.</li><li><strong>The name.</strong> <em>Jules&#39; Utility Class Extensions.</em><sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1:1]</a></sup></li></ul><p>Today JUCE is dual-licensed: AGPLv3 or a commercial licence.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup> This page does not claim what the licence was at the 2004 release, because no source for that was found.</p><h3 id="modularisation-and-the-introjucer" tabindex="-1">Modularisation and the Introjucer <a class="header-anchor" href="#modularisation-and-the-introjucer" aria-label="Permalink to &quot;Modularisation and the Introjucer&quot;">​</a></h3><p>JUCE is organised into <strong>modules</strong>, each with a machine-readable declaration block. That lets a tool assemble projects from them: the <strong>Introjucer</strong>, which generated IDE projects. <code>CHANGE_LIST.md</code> mentions the Introjucer as early as version 3.3.0.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup> The module format was simplified in JUCE 4.2, when the JSON module definition files were removed, and it is still used today (see <a href="./build-systems.html">Build systems</a>).<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup> This repository does not record which release first introduced modules, so this page does not say.</p><h3 id="the-roli-years-2014–2020" tabindex="-1">The ROLI years (2014–2020) <a class="header-anchor" href="#the-roli-years-2014–2020" aria-label="Permalink to &quot;The ROLI years (2014–2020)&quot;">​</a></h3><p>The music-technology company <strong>ROLI</strong> acquired JUCE and Raw Material Software in November 2014.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2:1]</a></sup> The change list records ROLI-era work such as an API and examples for ROLI Blocks in 4.3.0.<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup> Highlights from the change list:</p><ul><li><strong>JUCE 4</strong>: the <strong>Projucer</strong> arrived as &quot;Initial release of the Projucer!&quot; in 4.0.1.<sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup> Its live C++ compilation engine was initially closed source. In 4.2 it was merged with the Introjucer into a single open-source app.<sup class="footnote-ref"><a href="#fn5" id="fnref5:1">[5:1]</a></sup> Also OSC (<code>juce_osc</code>, 4.0.1) and multi-bus support for plug-in clients (4.1).<sup class="footnote-ref"><a href="#fn7" id="fnref7:1">[7:1]</a></sup><sup class="footnote-ref"><a href="#fn8" id="fnref8">[8]</a></sup></li><li><strong>JUCE 5</strong>: a new licensing model, the standalone plug-in format, and a codebase modernised to C++11/14.<sup class="footnote-ref"><a href="#fn9" id="fnref9">[9]</a></sup> <strong><code>juce_dsp</code></strong> was released in 5.1.0, <strong><code>juce_analytics</code></strong> arrived in 5.2.0, and an in-app purchases module in 5.1.2.<sup class="footnote-ref"><a href="#fn10" id="fnref10">[10]</a></sup></li></ul><h3 id="the-pace-years-2020–present" tabindex="-1">The PACE years (2020–present) <a class="header-anchor" href="#the-pace-years-2020–present" aria-label="Permalink to &quot;The PACE years (2020–present)&quot;">​</a></h3><p><strong>PACE Anti-Piracy</strong>, known for iLok and AAX signing,<sup class="footnote-ref"><a href="#fn11" id="fnref11">[11]</a></sup> acquired JUCE from ROLI, announced in April 2020.<sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2:2]</a></sup> Releases since then focus on modern build tooling, rendering, and standards:</p><ul><li><strong>JUCE 6 (2020)</strong>: the <strong>CMake API</strong>, headless Linux support, VST3 on Linux, a revamped DSP module, and removal of the Projucer&#39;s sign-in requirement and analytics.<sup class="footnote-ref"><a href="#fn12" id="fnref12">[12]</a></sup></li><li><strong>JUCE 7 (2022)</strong>: <strong>ARA</strong> (Audio Random Access) support, <strong>LV2</strong> authoring and hosting, new macOS and iOS renderers, a reworked <code>AudioPlayHead</code>, and better accessibility.<sup class="footnote-ref"><a href="#fn13" id="fnref13">[13]</a></sup> <strong>MIDI-CI</strong> support (<code>juce_midi_ci</code>) followed in 7.0.9.<sup class="footnote-ref"><a href="#fn10" id="fnref10:1">[10:1]</a></sup></li><li><strong>JUCE 8 (2024)</strong>: a <strong>Direct2D</strong> renderer on Windows, <strong>WebView-based UIs</strong>, consistent Unicode text handling, the <strong><code>juce_animation</code></strong> module, and the AAX SDK bundled.<sup class="footnote-ref"><a href="#fn14" id="fnref14">[14]</a></sup> The open-source licence moved from GPLv3 to <strong>AGPLv3</strong>: the <code>LICENSE.md</code> at tag 7.0.12 describes GPLv3, and the one at 8.0.0 says the modules are dual-licensed under AGPLv3.<sup class="footnote-ref"><a href="#fn15" id="fnref15">[15]</a></sup> JavaScript support moved into its own <strong><code>juce_javascript</code></strong> module in 8.0.4. <strong><code>juce_audio_processors_headless</code></strong> split the GUI-free half of plug-in support out of <code>juce_audio_processors</code> in 8.0.11. That release also moved to the MIT-licensed VST3 SDK 3.8.0.<sup class="footnote-ref"><a href="#fn10" id="fnref10:2">[10:2]</a></sup></li><li><strong>JUCE 9 (July 2026)</strong>: a new SVG parser, variable fonts, a new macOS CoreAudio implementation, a faster software renderer, OpenGL ES on Linux, better multi-touch, and a CMake build that works better in headless environments. Point releases have added Opus and WebP support, enabled <code>MP3AudioFormat</code> by default, and published a TypeScript npm package for WebView integration.<sup class="footnote-ref"><a href="#fn16" id="fnref16">[16]</a></sup></li></ul><h2 id="recent-release-cadence" tabindex="-1">Recent release cadence <a class="header-anchor" href="#recent-release-cadence" aria-label="Permalink to &quot;Recent release cadence&quot;">​</a></h2><p>From this fork&#39;s git history (commits titled &quot;JUCE version x.y.z&quot;):<sup class="footnote-ref"><a href="#fn17" id="fnref17">[17]</a></sup></p><table tabindex="0"><thead><tr><th>Version</th><th>Date</th></tr></thead><tbody><tr><td>9.0.3</td><td>2026-09-28</td></tr><tr><td>9.0.2</td><td>2026-09-07</td></tr><tr><td>9.0.1</td><td>2026-08-10</td></tr><tr><td>9.0.0</td><td>2026-07-21</td></tr><tr><td>8.0.15</td><td>2026-07-21</td></tr><tr><td>8.0.14</td><td>2026-06-22</td></tr><tr><td>8.0.13</td><td>2026-05-19</td></tr><tr><td>8.0.12</td><td>2025-12-16</td></tr></tbody></table><h2 id="when-each-module-arrived" tabindex="-1">When each module arrived <a class="header-anchor" href="#when-each-module-arrived" aria-label="Permalink to &quot;When each module arrived&quot;">​</a></h2><p>Reconstructed from <code>CHANGE_LIST.md</code>.<sup class="footnote-ref"><a href="#fn10" id="fnref10:3">[10:3]</a></sup> Modules without an entry predate the change list&#39;s detail, or arrived without a headline mention.</p><table tabindex="0"><thead><tr><th>Module</th><th>First mentioned</th></tr></thead><tbody><tr><td><code>juce_osc</code></td><td>4.0.1 (&quot;Full OSC support!&quot;)</td></tr><tr><td><code>juce_dsp</code></td><td>5.1.0</td></tr><tr><td>In-app purchases (now part of <code>juce_product_unlocking</code>)</td><td>5.1.2</td></tr><tr><td><code>juce_analytics</code></td><td>5.2.0</td></tr><tr><td><code>juce_midi_ci</code></td><td>7.0.9</td></tr><tr><td><code>juce_animation</code></td><td>8.0.0</td></tr><tr><td><code>juce_javascript</code></td><td>8.0.4 (split out of <code>juce_core</code>)</td></tr><tr><td><code>juce_audio_processors_headless</code></td><td>8.0.11 (split out of <code>juce_audio_processors</code>)</td></tr></tbody></table><h2 id="why-history-matters-when-you-read-code" tabindex="-1">Why history matters when you read code <a class="header-anchor" href="#why-history-matters-when-you-read-code" aria-label="Permalink to &quot;Why history matters when you read code&quot;">​</a></h2><ul><li><strong>Old tutorials use old APIs.</strong> Before trusting a forum post, check <a href="https://github.com/andrewh/JUCE/blob/master/BREAKING_CHANGES.md" target="_blank" rel="noreferrer"><code>BREAKING_CHANGES.md</code></a> for the versions in between. It lists breaking changes per release with a workaround.</li><li><strong>Look-and-feel versions</strong> (<code>LookAndFeel_V1</code> to <code>V4</code>) are fossils of past visual styles, kept for compatibility.</li><li><strong>Parallel APIs</strong> often coexist, such as <code>ScopedPointer</code> (gone) and <code>std::unique_ptr</code>, or listener interfaces and <code>std::function</code> callbacks (<code>onClick</code>). The newer one is usually preferred.</li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p><a href="https://en.wikipedia.org/wiki/JUCE" target="_blank" rel="noreferrer">JUCE, Wikipedia</a>: name &quot;Jules&#39; Utility Class Extensions&quot;; first released to the public in 2004; created from the code underneath the Tracktion DAW. Retrieved 2026-09-29; Wikipedia was opened, MusicRadar and Synthtopia were read as search-result summaries. <a href="#fnref1" class="footnote-backref">↩︎</a> <a href="#fnref1:1" class="footnote-backref">↩︎</a></p></li><li id="fn2" class="footnote-item"><p>ROLI acquisition in November 2014 and sale to PACE in April 2020: <a href="https://en.wikipedia.org/wiki/JUCE" target="_blank" rel="noreferrer">JUCE, Wikipedia</a>; <a href="https://www.musicradar.com/news/ilok-developer-pace-acquires-the-juce-development-framework-from-roli" target="_blank" rel="noreferrer">PACE acquires JUCE from ROLI, MusicRadar</a>; <a href="https://www.synthtopia.com/content/2020/04/22/pace-acquires-juce-audio-development-platform-from-roli/" target="_blank" rel="noreferrer">PACE Acquires JUCE, Synthtopia</a>. Retrieved 2026-09-29; Wikipedia was opened, MusicRadar and Synthtopia were read as search-result summaries. <a href="#fnref2" class="footnote-backref">↩︎</a> <a href="#fnref2:1" class="footnote-backref">↩︎</a> <a href="#fnref2:2" class="footnote-backref">↩︎</a></p></li><li id="fn3" class="footnote-item"><p><a href="https://github.com/andrewh/JUCE/blob/master/LICENSE.md" target="_blank" rel="noreferrer"><code>LICENSE.md</code></a>: &quot;dual-licensed under the AGPLv3 and the commercial JUCE licence&quot;. <a href="#fnref3" class="footnote-backref">↩︎</a></p></li><li id="fn4" class="footnote-item"><p><a href="https://github.com/andrewh/JUCE/blob/master/CHANGE_LIST.md" target="_blank" rel="noreferrer"><code>CHANGE_LIST.md</code>, Version 3.3.0</a>: &quot;New command-line options in the introjucer&quot;. <a href="#fnref4" class="footnote-backref">↩︎</a></p></li><li id="fn5" class="footnote-item"><p><code>CHANGE_LIST.md</code>, Version 4.2: simplified module format, Introjucer deleted and unified with the Projucer. <a href="#fnref5" class="footnote-backref">↩︎</a> <a href="#fnref5:1" class="footnote-backref">↩︎</a></p></li><li id="fn6" class="footnote-item"><p><code>CHANGE_LIST.md</code>, Version 4.3.0: &quot;Added API and examples for ROLI Blocks&quot;. <a href="#fnref6" class="footnote-backref">↩︎</a></p></li><li id="fn7" class="footnote-item"><p><code>CHANGE_LIST.md</code>, Version 4.0.1: &quot;Initial release of the Projucer!&quot; and &quot;Full OSC support!&quot;. <a href="#fnref7" class="footnote-backref">↩︎</a> <a href="#fnref7:1" class="footnote-backref">↩︎</a></p></li><li id="fn8" class="footnote-item"><p><code>CHANGE_LIST.md</code>, Version 4.1: &quot;Added multi-bus support for audio plug-in clients&quot;. <a href="#fnref8" class="footnote-backref">↩︎</a></p></li><li id="fn9" class="footnote-item"><p><code>CHANGE_LIST.md</code>, Version 5.0.0. <a href="#fnref9" class="footnote-backref">↩︎</a></p></li><li id="fn10" class="footnote-item"><p><code>CHANGE_LIST.md</code>, Versions 5.1.0, 5.1.2, 5.2.0, 7.0.9, 8.0.0, 8.0.4 and 8.0.11. <a href="#fnref10" class="footnote-backref">↩︎</a> <a href="#fnref10:1" class="footnote-backref">↩︎</a> <a href="#fnref10:2" class="footnote-backref">↩︎</a> <a href="#fnref10:3" class="footnote-backref">↩︎</a></p></li><li id="fn11" class="footnote-item"><p>iLok: <a href="https://www.musicradar.com/news/ilok-developer-pace-acquires-the-juce-development-framework-from-roli" target="_blank" rel="noreferrer">MusicRadar headline, &quot;iLok developer Pace acquires the JUCE development framework from ROLI&quot;</a>. AAX signing: <a href="https://github.com/andrewh/JUCE/blob/master/README.md#aax-plug-ins" target="_blank" rel="noreferrer"><code>README.md</code>, &quot;AAX Plug-Ins&quot;</a>. <a href="#fnref11" class="footnote-backref">↩︎</a></p></li><li id="fn12" class="footnote-item"><p><code>CHANGE_LIST.md</code>, Version 6.0.0. <a href="#fnref12" class="footnote-backref">↩︎</a></p></li><li id="fn13" class="footnote-item"><p><code>CHANGE_LIST.md</code>, Version 7.0.0. <a href="#fnref13" class="footnote-backref">↩︎</a></p></li><li id="fn14" class="footnote-item"><p><code>CHANGE_LIST.md</code>, Version 8.0.0. <a href="#fnref14" class="footnote-backref">↩︎</a></p></li><li id="fn15" class="footnote-item"><p><code>LICENSE.md</code> at <a href="https://raw.githubusercontent.com/juce-framework/JUCE/7.0.12/LICENSE.md" target="_blank" rel="noreferrer">tag 7.0.12</a> and <a href="https://raw.githubusercontent.com/juce-framework/JUCE/8.0.0/LICENSE.md" target="_blank" rel="noreferrer">tag 8.0.0</a> in the upstream repository. <a href="#fnref15" class="footnote-backref">↩︎</a></p></li><li id="fn16" class="footnote-item"><p><code>CHANGE_LIST.md</code>, Versions 9.0.0 to 9.0.3. <a href="#fnref16" class="footnote-backref">↩︎</a></p></li><li id="fn17" class="footnote-item"><p><code>git log</code> of this repository, commits &quot;JUCE version 8.0.12&quot; to &quot;JUCE version 9.0.3&quot;. The history starts in January 2025, so earlier release dates are not available here. <a href="#fnref17" class="footnote-backref">↩︎</a></p></li></ol></section>',31)])])}const p=t(s,[["render",n]]);export{u as __pageData,p as default};
